"use client";

/**
 * RadioGroup: choose one option from a short list.
 * Purpose: wraps Radix RadioGroup, which gives arrow-key movement between options. Generated by
 *   shadcn, then re-themed to Grove. Owner: design system.
 * Props: RadioGroup takes value, onValueChange, name, disabled; each RadioGroupItem takes a value and an id.
 * Responsive: a 22 px circle; put each item in a Label so the whole row is the click target.
 * Accessibility: one tab stop for the group, arrow keys move and select. Selected is shown by a
 *   filled dot, not colour alone.
 * States: unselected, selected, hover, focus, disabled.
 * Dependencies: radix RadioGroup, cn. Tests: controls.test.tsx; Design Lab "Fields" (S2-T07).
 * UX reference: ds-components, Fields (c-core.css .radio).
 */
import { RadioGroup as RadioGroupPrimitive } from "radix-ui";
import type { ComponentProps } from "react";
import { cn } from "@/lib/cn";

function RadioGroup({ className, ...props }: ComponentProps<typeof RadioGroupPrimitive.Root>) {
  return (
    <RadioGroupPrimitive.Root
      data-slot="radio-group"
      className={cn("grid gap-3", className)}
      {...props}
    />
  );
}

function RadioGroupItem({ className, ...props }: ComponentProps<typeof RadioGroupPrimitive.Item>) {
  return (
    <RadioGroupPrimitive.Item
      data-slot="radio-group-item"
      className={cn(
        "grid aspect-square size-(--size-check) shrink-0 place-content-center rounded-pill border-[length:var(--bw-field)] border-line-input bg-surface",
        "transition-colors duration-(--dur-fast) hover:border-primary data-[state=checked]:border-primary",
        "aria-invalid:border-[length:var(--bw-error)] aria-invalid:border-danger",
        "disabled:cursor-not-allowed disabled:border-line-strong disabled:bg-canvas-sunken",
        className,
      )}
      {...props}
    >
      <RadioGroupPrimitive.Indicator
        data-slot="radio-group-indicator"
        className="grid place-content-center"
      >
        <span className="size-2.5 rounded-pill bg-primary" />
      </RadioGroupPrimitive.Indicator>
    </RadioGroupPrimitive.Item>
  );
}

export { RadioGroup, RadioGroupItem };
